def as_list(value):
	if isinstance(value, str):
		try:
			value = json.loads(value)
		except:
			value = value.split("\n")
	if not isinstance(value, list):
		return []
	return [str(v) for v in value if str(v).strip()]

def split_row(raw, count):
	parts = [p.strip() for p in str(raw).split("|")]
	while len(parts) < count:
		parts.append("")
	return parts

def slugify(value):
	chars = [c if c.isalnum() else "-" for c in str(value).lower()]
	slug = "".join(chars)
	while "--" in slug:
		slug = slug.replace("--", "-")
	return slug.strip("-") or "item"

def minutes(value):
	try:
		bits = str(value).strip().split(":")
		return int(bits[0]) * 60 + int(bits[1])
	except:
		return -1

def clock(total):
	return str(total // 60).zfill(2) + ":" + str(total % 60).zfill(2)

def number(value, fallback):
	try:
		result = float(value)
		return result if result > 0 else fallback
	except:
		return fallback

def ems(value, table):
	total = 0.0
	for ch in str(value).upper():
		total = total + table.get(ch, 0.22) + 0.02
	return round(total, 3)

def anchor(day, start, room, slug):
	# a session's id: day, start and the room's first word ("thu-0930-main"); whole-room breaks
	# carry no room. The hero, the lineup and the speaker index link to the same ids.
	key = slug(day)[:3]
	stamp = str(start).strip().replace(":", "")
	place = str(room).strip().lower()
	if place in ["", "all", "every room", "everywhere"]:
		return key + "-" + stamp
	return key + "-" + stamp + "-" + slug(place.split(" ")[0])

def weekday(iso):
	names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
	months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]
	offsets = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
	try:
		bits = str(iso).strip().split("-")
		year = int(bits[0])
		month = int(bits[1])
		day = int(bits[2])
		y = year - 1 if month < 3 else year
		index = (y + y // 4 - y // 100 + y // 400 + offsets[month - 1] + day) % 7
		return {"name": names[index], "date": str(day) + " " + months[month - 1]}
	except:
		return {"name": "", "date": ""}

